    # Run FCI algorithm
    graph, edges = cl_fci(data_values, **all_params)

    # Convert the graph to adjacency matrix
    adj_matrix = self.convert_to_adjacency_matrix(graph)

    # Prepare additional information
    info = {
        'edges': edges,
        'graph': graph,
    }

    return adj_matrix, info, (graph, edges)

