    self._secondary_param_keys = ['lambda_2', 'learning_rate', 'equal_variances',
                                  'checkpoint_iter', 'seed', 'device_type', 'device_ids']
    return {k: v for k, v in self._params.items() if k in self._secondary_param_keys}

