def kci_pruning(data, revised_graph):
    from causallearn.utils.cit import CIT
    kci_forbid_dict = {}
    test = CIT(data.to_numpy(), 'kci') # construct a CIT instance with data and method name
    for idx_1 in range(len(data.columns)-1):
